'use strict'; const { BRAND, PACKAGES, REGIONS, wa } = require('./config'); const { COUNTRIES, REVIEWS, FAQS, BLOG_POSTS } = require('./data'); const L = require('./layout'); const { icon, img, flag, stars, countryCard, reviewCard, faqBlock, sectionHead, ctaBand, pageHero, packageCard, page, breadcrumbs } = L; const HOME_PICKS = [ 'france', 'italy', 'spain', 'germany', 'greece', 'portugal', 'switzerland', 'netherlands', 'austria', 'iceland', 'croatia', 'czech-republic' ]; const bySlug = (slug) => COUNTRIES.find((c) => c.slug === slug); const regionLabel = (id) => (REGIONS.find((r) => r.id === id) || {}).label || ''; function homeCards() { return HOME_PICKS.map((slug) => countryCard(bySlug(slug))).join(''); } function allCards() { return COUNTRIES.map(countryCard).join(''); } function countryPills() { return `<div class="pills">${COUNTRIES.map((c) => `<a class="pill" href="${c.slug}.html">${c.name}</a>`).join('')}</div>`; } function baseJsonLd() { return [ { '@context': 'https://schema.org', '@type': 'ProfessionalService', '@id': `${BRAND.domain}/#organization`, name: `${BRAND.name} (${BRAND.legalName})`, url: BRAND.domain, description: 'UK-based Schengen visa consultancy helping applicants prepare documents, book appointments and file visa applications for all 29 Schengen countries.', telephone: BRAND.phoneHref, email: BRAND.email, priceRange: 'GBP 99-250', address: { '@type': 'PostalAddress', streetAddress: BRAND.address.line1, addressLocality: BRAND.address.city, addressRegion: BRAND.address.county, postalCode: BRAND.address.postcode, addressCountry: 'GB' }, areaServed: [{ '@type': 'Country', name: 'United Kingdom' }, { '@type': 'Place', name: 'Schengen Area' }], openingHours: 'Mo-Sa 09:00-18:00' }, { '@context': 'https://schema.org', '@type': 'WebSite', '@id': `${BRAND.domain}/#website`, url: BRAND.domain, name: BRAND.name, publisher: { '@id': `${BRAND.domain}/#organization` }, inLanguage: 'en-GB' } ]; } function faqJsonLd(items) { return { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: items.map((f) => ({ '@type': 'Question', name: f.q, acceptedAnswer: { '@type': 'Answer', text: f.a.replace(/<[^>]+>/g, '') } })) }; } /* ------------------------------------------------------------------ HOME */ function home() { const heroImage = img('photo-1502602898657-3e91760cbb34', 2200, 80); const faqs = FAQS.slice(0, 7); const content = ` <section class="hero"> <div class="hero__media"> <img src="${heroImage}" alt="The Eiffel Tower lit up over Paris at dusk" width="2200" height="1467" fetchpriority="high" decoding="async"> </div> <div class="hero__veil" aria-hidden="true"></div> <div class="shell hero__inner"> <span class="hero__eyebrow">${icon('spark')} UK-based Schengen visa specialists</span> <h1 class="hero__title">Your Schengen visa,<br>prepared by <em>specialists who answer the phone.</em></h1> <p class="hero__lede">Appointment booking, full document preparation and application support for all 29 Schengen countries. One dedicated named consultant, from your first message to your decision.</p> <form class="hero-search" action="visas.html" method="get" role="search"> <label for="heroDest">Where are you going?</label> <div class="hero-search__row"> <div class="hero-search__input"> ${icon('search')} <input id="heroDest" name="q" list="countryList" placeholder="Search 29 countries &mdash; France, Italy, Spain&hellip;" autocomplete="off"> </div> <button class="btn btn--primary" type="submit">Find my visa ${icon('arrow')}</button> </div> </form> <datalist id="countryList">${COUNTRIES.map((c) => `<option value="${c.name}"></option>`).join('')}</datalist> <div class="hero__actions"> <a class="hero__wa" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} Chat with a visa expert</a> <span class="hero__note">${icon('clock')} Replies Mon&ndash;Sat, 9:00&ndash;18:00</span> </div> <ul class="hero__stats"> <li><b>29</b><span>Schengen countries</span></li> <li><b>&pound;80</b><span>From fixed fee</span></li> <li><b>1 consultant</b><span>Dedicated named consultant</span></li> <li><b>Mon&ndash;Sat</b><span>9:00&ndash;18:00 UK time</span></li> </ul> </div> </section> <div class="shell"> <ul class="valuebar reveal"> <li>${icon('calendar')}<span><b>Appointment booking</b>Slots secured in your name</span></li> <li>${icon('file')}<span><b>Document preparation</b>A checklist built for your trip</span></li> <li>${icon('shield')}<span><b>Application filing</b>Checked before it is submitted</span></li> <li>${icon('chat')}<span><b>WhatsApp support</b>One named consultant, start to finish</span></li> </ul> </div> <section class="section" id="destinations"> <div class="shell"> ${sectionHead({ eyebrow: 'Visa services', title: 'Find visa support for <em>your destination.</em>', text: 'Choose a country to see the visa requirements, the documents we check and how our UK team can help.', action: `<a class="btn btn--ghost" href="visas.html">All 29 countries ${icon('arrow')}</a>` })} <div class="dgrid">${homeCards()}</div> </div> </section> <section class="section section--cream" id="pricing"> <div class="shell deposit"> <div class="deposit__copy reveal"> <span class="eyebrow">Schengen pay later</span> <h2 class="section-title">Full service support.<br>Just &pound;49 to start.</h2> <p class="lead">Start your Schengen application with a &pound;49 deposit per traveller. Pay the balance once your appointment is booked &mdash; or before we submit an application that does not need one.</p> <ul class="ticks"> <li>${icon('check')} Your consultant starts the moment you pay the deposit</li> <li>${icon('check')} The balance is only due when your appointment is booked</li> <li>${icon('check')} The same full service as paying in full</li> <li>${icon('check')} No interest, no extra fees</li> </ul> <div class="btn-row"> <a class="btn btn--primary" href="apply.html?package=full&amp;deposit=1">Start for &pound;49 ${icon('arrow')}</a> <a class="btn btn--ghost" href="pricing.html">See what is included</a> </div> </div> <div class="paycard reveal"> <div class="paycard__head"> <div> <span>Full application support</span> <strong>End-to-end Schengen visa assistance</strong> </div> <div class="paycard__total"><small>Total</small><b>&pound;165</b><span>per traveller</span></div> </div> <ol class="payline"> <li> <span class="payline__num">1</span> <div><b>Today</b><p>Pay the deposit. Your consultant builds your checklist and starts on your application.</p></div> <strong>&pound;49</strong> </li> <li> <span class="payline__num">2</span> <div><b>Next</b><p>We prepare and check your file and, where your visa needs one, book your appointment.</p></div> <strong>&mdash;</strong> </li> <li> <span class="payline__num">3</span> <div><b>Then</b><p>Pay the balance once your appointment is booked, or before we submit a visa that has no appointment.</p></div> <strong>&pound;116</strong> </li> </ol> <p class="paycard__foot">Government and visa-centre fees are separate. Appointment-only support is &pound;99.</p> </div> </div> </section> <section class="section" id="how"> <div class="shell"> ${sectionHead({ eyebrow: 'How it works', title: 'Your application, <em>step by step.</em>', text: 'Our UK team prepares and checks the file with you, from the first question to the decision. You always know what happens next.', action: `<a class="btn btn--ghost" href="how-it-works.html">The full process ${icon('arrow')}</a>` })} <div class="steps"> <article class="step reveal"> <div class="step__media"><img src="${img('photo-1488646953014-85cb44e25828', 900, 78)}" alt="A map and travel notes on a table" loading="lazy" width="900" height="600"><span class="step__num">01</span></div> <div class="step__body"><h3>Tell us your plan</h3><p>A 5-minute form or a WhatsApp message. We confirm the exact consulate rule and the VFS/TLS appointment centre.</p></div> </article> <article class="step reveal"> <div class="step__media"><img src="${img('photo-1450101499163-c8848c66ca85', 900, 78)}" alt="Application paperwork laid out beside a laptop" loading="lazy" width="900" height="600"><span class="step__num">02</span></div> <div class="step__body"><h3>We map the route</h3><p>We confirm the correct consulate, appointment centre and submission route before any fee is agreed.</p></div> </article> <article class="step reveal"> <div class="step__media"><img src="${img('photo-1521791136064-7986c2920216', 900, 78)}" alt="Two people reviewing documents across a desk" loading="lazy" width="900" height="600"><span class="step__num">03</span></div> <div class="step__body"><h3>Documents reviewed</h3><p>Every page is checked by a specialist, with a written gap list before submission.</p></div> </article> <article class="step reveal"> <div class="step__media"><img src="${img('photo-1436491865332-7a61a109cc05', 900, 78)}" alt="An aircraft wing above the clouds at sunrise" loading="lazy" width="900" height="600"><span class="step__num">04</span></div> <div class="step__body"><h3>Appointment &amp; submission</h3><p>Biometric slot booked, forms completed, day-of briefing provided.</p></div> </article> <article class="step reveal"> <div class="step__media"><img src="${img('photo-1502602898657-3e91760cbb34', 900, 78)}" alt="Travel planning notes and a passport" loading="lazy" width="900" height="600"><span class="step__num">05</span></div> <div class="step__body"><h3>Decision &amp; travel</h3><p>The file is tracked through to passport return.</p></div> </article> </div> </div> </section> <section class="section section--ink" id="why"> <div class="shell"> <div class="why__head reveal"> <span class="eyebrow eyebrow--light">Why Visalade</span> <h2 class="section-title">A visa file is only as strong as its <em>weakest document.</em></h2> <p>That is why we read the whole thing before it leaves your hands. No call centre, no template advice, no guessing.</p> </div> <div class="features"> <article class="feature reveal">${icon('card')}<h3>Fixed fees, agreed upfront</h3><p>No percentage of your trip and no surprise add-ons. You approve the full service fee before we start.</p></article> <article class="feature reveal">${icon('users')}<h3>One named consultant</h3><p>The same person answers your messages from the first question to the decision. They know your file.</p></article> <article class="feature reveal">${icon('shield')}<h3>A real document check</h3><p>Dates, names, balances and bookings compared line by line &mdash; before the consulate sees them.</p></article> <article class="feature reveal">${icon('calendar')}<h3>Appointment handled</h3><p>We monitor availability, book the slot in your name and tell you exactly what to bring on the day.</p></article> </div> <div class="why__strip reveal"> <span>${icon('lock')} Your documents stay confidential</span> <span>${icon('globe')} All 29 Schengen countries</span> <span>${icon('clock')} Mon&ndash;Sat, 9:00&ndash;18:00</span> </div> </div> </section> <section class="section" id="reviews"> <div class="shell"> ${sectionHead({ eyebrow: 'Reviews', title: 'What our travellers <em>say.</em>', text: 'Published on Google, unedited. Every review below names the consultant who handled the file.', action: `<div class="score"><b>${BRAND.rating}</b>${stars()}<span>${BRAND.reviewCount} verified reviews</span></div>` })} <div class="reviews">${REVIEWS.map(reviewCard).join('')}</div> <div class="center"><a class="btn btn--ghost" href="${BRAND.googleReviewUrl}" target="_blank" rel="noopener">Read every review on Google ${icon('external')}</a></div> </div> </section> <section class="section section--tint" id="faq"> <div class="shell"> ${sectionHead({ eyebrow: 'FAQs', title: 'Things people <em>ask us.</em>', text: 'The honest answers, including what we cannot do.', action: `<a class="btn btn--ghost" href="faq.html">All FAQs ${icon('arrow')}</a>` })} ${faqBlock(faqs, 'home-faq')} </div> </section> ${ctaBand({})} `; return page({ title: 'Schengen Visa Specialists UK | Appointment & Document Support | Visalade', description: 'UK-based Schengen visa specialists. We book appointments, prepare your documents and file your application for all 29 Schengen countries. Fixed fees from £99.', canonical: '', active: 'home', bodyClass: 'home', content, jsonLd: [ ...baseJsonLd(), { '@context': 'https://schema.org', '@type': 'Service', name: 'Schengen Visa Application Support', provider: { '@id': `${BRAND.domain}/#organization` }, areaServed: { '@type': 'Place', name: 'Schengen Area' }, offers: PACKAGES.map((p) => ({ '@type': 'Offer', name: p.name, price: p.price, priceCurrency: 'GBP', description: p.description })) }, faqJsonLd(faqs) ] }); } /* ----------------------------------------------------------------- VISAS */ function visas() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'All visas' }], eyebrow: '29 Schengen countries', title: 'Visa support for <em>your destination.</em>', text: 'Every country in the Schengen area, with the same clear process: we confirm the visa, check the documents and handle the appointment.', stats: [ { value: '29', label: 'Countries covered' }, { value: '&pound;99', label: 'Starting fee' }, { value: '15&ndash;45', label: 'Day decisions' }, { value: '90/180', label: 'Days in the area' } ] })} <section class="section section--tight"> <div class="shell"> <div class="visa-toolbar reveal"> <div class="searchbox"> ${icon('search')} <label class="sr-only" for="destSearch">Search a country</label> <input id="destSearch" type="search" placeholder="Search a country&hellip;" autocomplete="off"> </div> <div class="chips" role="group" aria-label="Filter by region"> <button class="chip is-active" type="button" data-filter="all">All 29</button> ${REGIONS.map((r) => `<button class="chip" type="button" data-filter="${r.id}">${r.label}</button>`).join('')} </div> </div> <p class="result-count" id="destCount" aria-live="polite">Showing 29 countries</p> <div class="dgrid dgrid--all" id="destGrid">${allCards()}</div> <p class="empty" id="destEmpty" hidden>No country matches that search. <a href="contact.html">Tell us where you are going</a> and we will point you in the right direction.</p> </div> </section> <section class="section section--cream"> <div class="shell"> ${sectionHead({ eyebrow: 'Not sure which consulate?', title: 'The main-destination rule, <em>simply.</em>', text: 'You apply to the country where you will spend the most nights. If two countries are equal, apply to the one you enter first.' })} <div class="cards3"> <article class="info-card reveal"><span class="info-card__num">01</span><h3>Most nights</h3><p>Count the nights, not the flights. The country with the most overnight stays receives the application.</p></article> <article class="info-card reveal"><span class="info-card__num">02</span><h3>Equal nights</h3><p>If two or more countries share the highest number of nights, apply to the country you enter first.</p></article> <article class="info-card reveal"><span class="info-card__num">03</span><h3>Transit</h3><p>Some nationalities need an airport transit visa even when they stay airside. Check before booking a connection.</p></article> </div> <div class="center" style="margin-top:36px;"><a class="btn btn--primary" href="blog/which-schengen-country-to-apply-to.html">Read the full guide ${icon('arrow')}</a></div> </div> </section> ${ctaBand({ title: 'Tell us where you are going.', text: 'Send your destination and travel dates on WhatsApp. We will confirm the visa, the consulate and the next step. The first conversation is free.' })} `; return page({ title: 'All 29 Schengen Countries | Visa Support from the UK | Visalade', description: 'Browse visa support for all 29 Schengen countries. See requirements, document checklists and appointment help for France, Italy, Spain, Germany and more.', canonical: 'visas.html', active: 'visas', content, jsonLd: baseJsonLd() }); } /* -------------------------------------------------------------- SCHENGEN */ function schengen() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Schengen visa' }], eyebrow: 'The short-stay visa', title: 'One visa. <em>29 countries.</em>', text: 'A Schengen visa lets you travel across the Schengen area for up to 90 days in any 180-day period. We prepare the application for your main destination and the trip around it.', actions: `<a class="btn btn--primary" href="apply.html">Start an application ${icon('arrow')}</a><a class="btn btn--ghost" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} Ask a question</a>`, aside: `<div class="mini-card"> <span class="mini-card__label">Typical short-stay visa</span> <div class="mini-card__row"><span>Government fee</span><b>&euro;90</b></div> <div class="mini-card__row"><span>Maximum stay</span><b>90 days</b></div> <div class="mini-card__row"><span>Validity window</span><b>180 days</b></div> <div class="mini-card__row"><span>Decision time</span><b>15&ndash;45 days</b></div> <p>Fees and timings are set by the consulate and can change. We confirm the current position before you pay.</p> </div>` })} <section class="section"> <div class="shell content-grid"> <div class="prose reveal"> <h2>What is a Schengen visa?</h2> <p>The Schengen visa is a short-stay visa (Type C) for visits of up to 90 days in any 180-day period. It is issued by one Schengen country but lets you move freely through the whole Schengen area once you are inside.</p> <p>There are 29 Schengen countries: Austria, Belgium, Bulgaria, Croatia, Czech Republic, Denmark, Estonia, Finland, France, Germany, Greece, Hungary, Iceland, Italy, Latvia, Liechtenstein, Lithuania, Luxembourg, Malta, Netherlands, Norway, Poland, Portugal, Romania, Slovakia, Slovenia, Spain, Sweden and Switzerland.</p> <h2>Who needs one?</h2> <p>It depends on your passport, not where you live. British passport holders do not need a Schengen visa for short tourism, business or family visits. If you hold a non-British passport, you may need one &mdash; even if you have lived in the UK for years.</p> <p>We check your nationality, your UK immigration status and the length of your leave to remain before advising. The consulate will want to see that you can legally return to the UK after the trip.</p> <h2>The 90/180 rule</h2> <p>You can spend a maximum of 90 days in the Schengen area in any rolling 180-day period. The count includes every Schengen country, not just the one that issued the visa. Days spent in the UK, Ireland and non-Schengen countries do not count.</p> <p>If you have travelled to the Schengen area recently, tell us the dates. We check the calculation before you apply, because a previous long stay can affect the new visa.</p> <h2>Which country do I apply to?</h2> <p>Apply to the country where you will spend the most nights. If two countries are equal, apply to the country you enter first. The country you fly into is not automatically the right one.</p> <p>We confirm the main destination and the correct visa application centre before any government fee is paid.</p> <h2>What the application includes</h2> <ul> <li>A completed and signed application form</li> <li>Passport and recent photographs</li> <li>Travel insurance with at least &euro;30,000 medical cover</li> <li>Flight reservations and proof of accommodation</li> <li>Bank statements and evidence of income</li> <li>Employment, study or business evidence</li> <li>Proof of UK immigration status, where applicable</li> <li>A short cover letter explaining the trip</li> </ul> <p>Our <a href="requirements.html">document checklist</a> explains each item in more detail.</p> <h2>How long does it take?</h2> <p>Most applications are decided within 15 calendar days of the consulate receiving the file, and many are faster. Complex files can take up to 45 days. Appointment availability varies by country and season, so start four to six weeks before travel where you can.</p> <h2>What we do</h2> <p>We build the checklist, review the evidence, complete the form, prepare the cover letter, book the appointment and tell you how to track the decision. You get one named consultant and a written fee before we start. The decision itself is made solely by the consulate.</p> </div> <aside class="sidebar reveal"> <div class="sidecard"> <span class="sidecard__eyebrow">Full support from</span> <div class="sidecard__price">&pound;165 <small>per traveller</small></div> <p>Or start with a &pound;49 deposit and pay the balance when your appointment is booked.</p> <a class="btn btn--primary btn--block" href="apply.html?package=full">Start my application ${icon('arrow')}</a> <a class="btn btn--ghost btn--block" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp us</a> <ul class="ticks ticks--sm"> <li>${icon('check')} Named consultant</li> <li>${icon('check')} Document review</li> <li>${icon('check')} Appointment booking</li> <li>${icon('check')} Fixed fee, agreed upfront</li> </ul> </div> </aside> </div> </section> <section class="section section--tint"> <div class="shell"> ${sectionHead({ eyebrow: 'Destinations', title: 'Choose your <em>country.</em>', text: 'Every Schengen country, with the same document standards and the same named consultant.' })} ${countryPills()} </div> </section> <section class="section"> <div class="shell"> ${sectionHead({ eyebrow: 'FAQs', title: 'Schengen visa <em>questions.</em>' })} ${faqBlock(FAQS.slice(0, 8), 'schengen-faq')} </div> </section> ${ctaBand({})} `; return page({ title: 'Schengen Visa from the UK | Requirements, Fees & Support | Visalade', description: 'What a Schengen visa covers, who needs one, the 90/180 rule, which country to apply to and the documents required. UK-based support for all 29 countries.', canonical: 'schengen.html', active: 'schengen', content, jsonLd: [...baseJsonLd(), faqJsonLd(FAQS.slice(0, 8))] }); } /* --------------------------------------------------------- HOW IT WORKS */ function howItWorks() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'How it works' }], eyebrow: 'The process', title: 'From first message to <em>decision.</em>', text: 'A clear, four-step process run by a small UK team. You always know what we are doing, what we need from you and what happens next.', actions: `<a class="btn btn--primary" href="apply.html">Start an application ${icon('arrow')}</a><a class="btn btn--ghost" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} Ask first</a>` })} <section class="section"> <div class="shell"> <div class="timeline"> <article class="tl reveal"> <div class="tl__media"><img src="${img('photo-1488646953014-85cb44e25828', 1000, 78)}" alt="Planning a trip with a map and notes" loading="lazy" width="1000" height="667"></div> <div class="tl__body"> <span class="tl__num">Step 01</span> <h2>Share your plans</h2> <p>Send your destination, travel dates, the purpose of the trip and the passport you travel on. We confirm which visa you need, which consulate has jurisdiction and which appointment centre you will use.</p> <ul class="ticks ticks--sm"> <li>${icon('check')} Main-destination check</li> <li>${icon('check')} Visa type confirmed</li> <li>${icon('check')} Written fee before you pay</li> </ul> </div> </article> <article class="tl reveal"> <div class="tl__media"><img src="${img('photo-1450101499163-c8848c66ca85', 1000, 78)}" alt="Paperwork and a laptop on a desk" loading="lazy" width="1000" height="667"></div> <div class="tl__body"> <span class="tl__num">Step 02</span> <h2>Send your documents</h2> <p>We build a checklist for your trip and your nationality. Send each item by WhatsApp or email as you gather it. There is no need to have everything ready before you start.</p> <ul class="ticks ticks--sm"> <li>${icon('check')} Personalised checklist</li> <li>${icon('check')} WhatsApp or email upload</li> <li>${icon('check')} We chase the gaps with you</li> </ul> </div> </article> <article class="tl reveal"> <div class="tl__media"><img src="${img('photo-1521791136064-7986c2920216', 1000, 78)}" alt="Two people reviewing a document together" loading="lazy" width="1000" height="667"></div> <div class="tl__body"> <span class="tl__num">Step 03</span> <h2>We check and file</h2> <p>Your consultant compares names, dates, balances and bookings across the whole file. We complete the form, prepare the cover letter, book the appointment and tell you exactly what to bring.</p> <ul class="ticks ticks--sm"> <li>${icon('check')} Line-by-line document review</li> <li>${icon('check')} Form and cover letter prepared</li> <li>${icon('check')} Appointment booked in your name</li> </ul> </div> </article> <article class="tl reveal"> <div class="tl__media"><img src="${img('photo-1436491865332-7a61a109cc05', 1000, 78)}" alt="An aircraft wing above the clouds" loading="lazy" width="1000" height="667"></div> <div class="tl__body"> <span class="tl__num">Step 04</span> <h2>Attend and track</h2> <p>Attend the appointment if your visa requires one. We explain how to track the decision, what to do if the consulate asks for more, and what your options are if the answer is no.</p> <ul class="ticks ticks--sm"> <li>${icon('check')} Appointment-day briefing</li> <li>${icon('check')} Decision tracking guidance</li> <li>${icon('check')} Post-decision support</li> </ul> </div> </article> </div> </div> </section> <section class="section section--cream"> <div class="shell content-grid"> <div class="prose reveal"> <h2>What we need from you</h2> <p>You do not need a perfect file to start. You need the basics and a bit of time. Most clients send documents over three or four days.</p> <ul> <li>Your passport and UK immigration evidence</li> <li>Your travel dates and a rough itinerary</li> <li>Bank statements for the last three to six months</li> <li>Proof of employment, study or business</li> <li>Travel insurance and accommodation bookings</li> <li>Any previous Schengen visas or refusal letters</li> </ul> <p>If something is missing or does not look right, we tell you early &mdash; not on the day of the appointment.</p> <h2>How long it takes</h2> <p>A straightforward file can be prepared in two to five working days once we have the documents. The consulate then takes up to 15 calendar days in most cases, or up to 45 for complex files. Appointment availability is the variable we cannot control, which is why we recommend starting four to six weeks before travel.</p> </div> <aside class="sidebar reveal"> <div class="sidecard sidecard--accent"> <span class="sidecard__eyebrow">Start today</span> <div class="sidecard__price">&pound;49 <small>deposit</small></div> <p>Begin full application support with a deposit. The balance is due when your appointment is booked.</p> <a class="btn btn--light btn--block" href="apply.html?package=full&amp;deposit=1">Start my application ${icon('arrow')}</a> <a class="btn btn--ghost btn--block" href="pricing.html">Compare packages</a> </div> </aside> </div> </section> <section class="section"> <div class="shell"> ${sectionHead({ eyebrow: 'FAQs', title: 'Before you <em>start.</em>' })} ${faqBlock(FAQS.slice(4, 10), 'how-faq')} </div> </section> ${ctaBand({ eyebrow: 'Ready when you are', title: 'Start with a conversation.', text: 'Tell us where you are going and when. We will confirm the visa and the next step before you pay anything.' })} `; return page({ title: 'How Our Schengen Visa Service Works | Step by Step | Visalade', description: 'See how our Schengen visa service works: destination and consulate check, document preparation, application review, appointment booking and decision tracking.', canonical: 'how-it-works.html', active: 'how', content, jsonLd: baseJsonLd() }); } /* --------------------------------------------------------------- PRICING */ const COMPARE = [ ['Appointments', true, true, true], ['Document checks', false, true, true], ['Application forms', false, true, true], ['Support access', true, true, true], ['Travel insurance (EUR 30,000 Schengen standard)', false, true, true], ['Previous refusals handled', false, true, true], ['Pricing transparency', true, true, true], ['Refund protection', true, true, true] ]; function pricing() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Pricing' }], eyebrow: 'Clear, fixed fees', title: 'Know the fee <em>before</em> you start.', text: 'Three ways to work with us. Every fee is quoted in writing and agreed before any work begins. Government and visa-centre fees are always separate.', stats: [ { value: '&pound;99', label: 'Appointment only' }, { value: '&pound;165', label: 'Full support' }, { value: '&pound;250', label: 'Premium' }, { value: '&pound;49', label: 'Deposit to start' } ] })} <section class="section section--tight"> <div class="shell"> ${sectionHead({ eyebrow: 'Services', title: 'Three ways to <em>work with us.</em>', text: 'Book the appointment, hand us the whole file, or keep a senior consultant on call from first question to decision.' })} <div class="price-grid">${PACKAGES.map((p) => packageCard(p)).join('')}</div> <p class="center muted small" style="margin-top:26px;">Prices are per traveller, in pounds sterling. Government and visa-centre fees are paid separately to the official channels.</p> </div> </section> <section class="section section--cream"> <div class="shell deposit"> <div class="deposit__copy reveal"> <span class="eyebrow">Pay later</span> <h2 class="section-title">Start with &pound;49.<br>Pay the rest <em>later.</em></h2> <p class="lead">Full application support and premium support can be started with a &pound;49 deposit per traveller. The balance is due once your appointment is booked, or before we submit an application that does not need an appointment.</p> <ul class="ticks"> <li>${icon('check')} No interest and no extra fee</li> <li>${icon('check')} Same service as paying in full</li> <li>${icon('check')} Cancel before work starts for a full refund of the deposit</li> </ul> <div class="btn-row"><a class="btn btn--primary" href="apply.html?package=full&amp;deposit=1">Start for &pound;49 ${icon('arrow')}</a></div> </div> <div class="paycard reveal"> <div class="paycard__head"> <div><span>Full application support</span><strong>Deposit and balance</strong></div> <div class="paycard__total"><small>Total</small><b>&pound;165</b><span>per traveller</span></div> </div> <ol class="payline"> <li><span class="payline__num">1</span><div><b>Today</b><p>Deposit paid. Your consultant is assigned and your checklist begins.</p></div><strong>&pound;49</strong></li> <li><span class="payline__num">2</span><div><b>When booked</b><p>Your appointment is confirmed, or your no-appointment file is ready to submit.</p></div><strong>&mdash;</strong></li> <li><span class="payline__num">3</span><div><b>Then</b><p>Balance paid before submission. No interest, no admin fee.</p></div><strong>&pound;116</strong></li> </ol> <p class="paycard__foot">Premium support is &pound;250, with the same &pound;49 deposit and a &pound;201 balance.</p> </div> </div> </section> <section class="section"> <div class="shell"> ${sectionHead({ eyebrow: 'Compare', title: 'What is included, <em>exactly.</em>' })} <div class="table-wrap reveal"> <table class="compare"> <thead><tr><th scope="col">Service</th><th scope="col">Appointment<br><span>&pound;99</span></th><th scope="col">Full support<br><span>&pound;165</span></th><th scope="col">Premium<br><span>&pound;250</span></th></tr></thead> <tbody> ${COMPARE.map((row) => `<tr><th scope="row">${row[0]}</th>${[1, 2, 3].map((i) => `<td>${row[i] ? `<span class="tick">${icon('check')}<span class="sr-only">Included</span></span>` : '<span class="dash" aria-hidden="true">&mdash;</span>'}</td>`).join('')}</tr>`).join('')} </tbody> </table> </div> <div class="cards3" style="margin-top:44px;"> <article class="info-card reveal">${icon('file')}<h3>What is not included</h3><p>Government visa fees, visa-centre service fees, travel insurance, flights, hotels and courier costs are separate. We tell you the expected amounts before you commit.</p></article> <article class="info-card reveal">${icon('refresh')}<h3>Changes and cancellations</h3><p>If your plans change, tell us as early as possible. Deposit refunds and rescheduling are set out in the <a href="refund-policy.html">refund policy</a>.</p></article> <article class="info-card reveal">${icon('shield')}<h3>No approval guarantee</h3><p>No consultancy can guarantee a visa. The decision belongs to the consulate. We guarantee the quality and completeness of the work we do.</p></article> </div> </div> </section> <section class="section section--tint"> <div class="shell"> ${sectionHead({ eyebrow: 'FAQs', title: 'Pricing <em>questions.</em>' })} ${faqBlock([FAQS[5], FAQS[6], FAQS[7], FAQS[10]], 'price-faq')} </div> </section> ${ctaBand({ title: 'Not sure which package?', text: 'Tell us your destination and travel dates. We will tell you honestly whether you need appointment-only or full support.' })} `; return page({ title: 'Schengen Visa Service Pricing | Fixed Fees from £99 | Visalade', description: 'Clear Schengen visa service pricing: appointment booking £99, full application support £165, premium £250. Start with a £49 deposit. Government fees separate.', canonical: 'pricing.html', active: 'pricing', content, jsonLd: [ ...baseJsonLd(), { '@context': 'https://schema.org', '@type': 'OfferCatalog', name: 'Schengen visa support packages', itemListElement: PACKAGES.map((p) => ({ '@type': 'Offer', name: p.name, price: p.price, priceCurrency: 'GBP', description: p.description })) } ] }); } /* ----------------------------------------------------------------- ABOUT */ function about() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'About' }], eyebrow: 'About Visalade', title: 'A small UK team that <em>answers.</em>', text: 'Visalade is the Schengen visa service of Travelade Limited, a UK-registered company. We help UK residents prepare, check and file Schengen visa applications without the guesswork.', actions: `<a class="btn btn--primary" href="apply.html">Start an application ${icon('arrow')}</a><a class="btn btn--ghost" href="contact.html">Contact the team</a>`, aside: `<div class="photo-card"><img src="${img('photo-1521737711867-e3b97375f902', 1000, 78)}" alt="A small team working together in an office" loading="lazy" width="1000" height="750"><div class="photo-card__tag">${icon('pin')} Chesham, Buckinghamshire</div></div>` })} <section class="section"> <div class="shell content-grid"> <div class="prose reveal"> <h2>Why we exist</h2> <p>Visa applications fail for ordinary reasons. A bank statement is three weeks old, a hotel booking does not cover the last night, a middle name is missing from the form, or the applicant applied to the wrong consulate. None of these are dramatic, and all of them are avoidable.</p> <p>We started Visalade because the process is stressful enough without feeling like you are guessing. Our job is to read the file the way a decision-maker will, tell you what is missing, and handle the administration so you can get on with the trip.</p> <h2>How we work</h2> <p>You get one named consultant, a written fee and a clear checklist. We do not use call-centre scripts or sell appointments we cannot deliver. If something in your file is likely to cause a problem, we say so early, while there is still time to fix it.</p> <p>We are an independent consultancy. We are not an embassy, consulate, VFS Global, TLScontact, BLS or any government body. The visa decision is made solely by the relevant authority.</p> <h2>Where we are</h2> <p>We are based in Chesham, Buckinghamshire. We work with clients across the UK by WhatsApp, email and phone, and we can arrange in-person support where it helps.</p> <p>Visalade is a trading name of Travelade Limited, registered in England &amp; Wales (company number ${BRAND.companyNo}).</p> </div> <aside class="sidebar reveal"> <div class="sidecard"> <span class="sidecard__eyebrow">At a glance</span> <ul class="facts-list"> <li><b>29</b><span>Schengen countries covered</span></li> <li><b>${BRAND.rating}/5</b><span>Google rating from ${BRAND.reviewCount} reviews</span></li> <li><b>UK</b><span>Based in Buckinghamshire</span></li> <li><b>2025</b><span>Founded</span></li> </ul> <a class="btn btn--primary btn--block" href="reviews.html">Read our reviews ${icon('arrow')}</a> </div> </aside> </div> </section> <section class="section section--cream"> <div class="shell"> ${sectionHead({ eyebrow: 'What we stand for', title: 'Three promises we <em>keep.</em>' })} <div class="cards3"> <article class="info-card reveal">${icon('chat')}<h3>Straight answers</h3><p>If we do not think you need our service, we will tell you. If a file is weak, we will explain why and what would strengthen it.</p></article> <article class="info-card reveal">${icon('card')}<h3>Fees you can see</h3><p>Our service fee is agreed in writing before work starts. Government fees are separate and paid to the official channel, never to us.</p></article> <article class="info-card reveal">${icon('lock')}<h3>Your data, handled carefully</h3><p>Documents are used only to prepare your application. We do not sell data, and we do not share it with anyone outside the application process.</p></article> </div> </div> </section> ${ctaBand({ title: 'Talk to a real person.', text: 'Send a message with your destination and travel dates. We will tell you what the application involves and whether we can help.' })} `; return page({ title: 'About Visalade | UK Schengen Visa Specialists | Travelade Limited', description: 'Visalade is a UK-based Schengen visa service run by Travelade Limited. One named consultant, fixed fees and a proper document check for all 29 countries.', canonical: 'about.html', active: 'about', content, jsonLd: baseJsonLd() }); } /* --------------------------------------------------------------- REVIEWS */ function reviewsPage() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Reviews' }], eyebrow: 'Reviews', title: 'Real files. <em>Real words.</em>', text: 'Every review below was published on Google. We have shortened long reviews only where needed, never reworded them.', aside: `<div class="score-card"> <b>${BRAND.rating}</b> ${stars()} <span>${BRAND.reviewCount} verified Google reviews</span> <a class="btn btn--ghost btn--block" href="${BRAND.googleReviewUrl}" target="_blank" rel="noopener">Read on Google ${icon('external')}</a> </div>` })} <section class="section section--tight"> <div class="shell"> <div class="reviews reviews--page">${REVIEWS.map(reviewCard).join('')}</div> </div> </section> <section class="section section--cream"> <div class="shell content-grid"> <div class="prose reveal"> <h2>What clients mention most</h2> <p>The same themes come up again and again: someone answers, the documents are explained properly, and the process feels less stressful than doing it alone.</p> <ul> <li>A named consultant who replies on WhatsApp</li> <li>Clear explanations of what each document is for</li> <li>Patience with first-time applicants</li> <li>Appointments booked without chasing</li> </ul> <p>We are a small team, so we cannot help everyone. If we are at capacity, we will tell you rather than take a file we cannot give proper attention to.</p> </div> <aside class="sidebar reveal"> <div class="sidecard sidecard--accent"> <span class="sidecard__eyebrow">Your turn</span> <div class="sidecard__price">Start today</div> <p>Tell us where you are going. We will confirm the visa and the next step before you pay anything.</p> <a class="btn btn--light btn--block" href="apply.html">Start an application ${icon('arrow')}</a> <a class="btn btn--ghost btn--block" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp us</a> </div> </aside> </div> </section> ${ctaBand({ title: 'Have a question before you start?', text: 'Send us your destination and dates. The first conversation is free and there is no pressure to book.' })} `; return page({ title: 'Reviews | Visalade | UK Schengen Visa Support', description: 'Read verified Google reviews from Visalade clients, and see what travellers say about our document checks, appointment booking and WhatsApp support.', canonical: 'reviews.html', active: 'reviews', content, jsonLd: [ ...baseJsonLd(), { '@context': 'https://schema.org', '@type': 'LocalBusiness', name: BRAND.name, image: BRAND.ogImage, telephone: BRAND.phoneHref, email: BRAND.email, address: { '@type': 'PostalAddress', streetAddress: BRAND.address.line1, addressLocality: BRAND.address.city, addressRegion: BRAND.address.county, postalCode: BRAND.address.postcode, addressCountry: 'GB' }, aggregateRating: { '@type': 'AggregateRating', ratingValue: BRAND.rating, reviewCount: BRAND.reviewCount }, review: REVIEWS.map((r) => ({ '@type': 'Review', author: { '@type': 'Person', name: r.name }, reviewRating: { '@type': 'Rating', ratingValue: '5', bestRating: '5' }, reviewBody: r.text })) } ] }); } /* ------------------------------------------------------------------- FAQ */ function faqPage() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'FAQs' }], eyebrow: 'FAQs', title: 'Straight answers, <em>before</em> you pay.', text: 'What we do, what we cannot do, and what the application actually involves. If your question is not here, send it on WhatsApp.', compact: true })} <section class="section section--tight"> <h2 class="sr-only">Frequently asked questions</h2> <div class="shell faq-layout"> <div>${faqBlock(FAQS, 'faq-page')}</div> <aside class="sidebar reveal"> <div class="sidecard"> <span class="sidecard__eyebrow">Still unsure?</span> <h3>Ask a consultant.</h3> <p>Send your destination, travel dates and the passport you hold. We will reply with the visa you need and the next step.</p> <a class="btn btn--primary btn--block" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp us</a> <a class="btn btn--ghost btn--block" href="contact.html">Other ways to contact</a> </div> </aside> </div> </section> ${ctaBand({ eyebrow: 'Ready when you are', title: 'Start with a conversation.', text: 'No obligation. Tell us where you are going and we will tell you what the application involves.' })} `; return page({ title: 'Schengen Visa FAQs | Fees, Documents & Timings | Visalade', description: 'Answers to the most common Schengen visa questions: who needs one, which country to apply to, fees, deposits, processing times, documents and refusals.', canonical: 'faq.html', active: 'faq', content, jsonLd: [...baseJsonLd(), faqJsonLd(FAQS)] }); } /* --------------------------------------------------------------- CONTACT */ function contact() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Contact' }], eyebrow: 'Contact', title: 'Tell us where you are <em>going.</em>', text: 'Send your destination and travel dates. We will confirm the visa, the consulate and the next step. The first conversation is free.', compact: true })} <section class="section section--tight"> <div class="shell contact-grid"> <div class="contact-cards"> <a class="contact-card reveal" href="${wa()}" target="_blank" rel="noopener"> ${icon('whatsapp')} <div><b>WhatsApp</b><span>Fastest reply, Mon&ndash;Sat</span></div> ${icon('external')} </a> <a class="contact-card reveal" href="tel:${BRAND.phoneHref}"> ${icon('phone')} <div><b>${BRAND.phone}</b><span>Call during office hours</span></div> ${icon('external')} </a> <a class="contact-card reveal" href="mailto:${BRAND.email}"> ${icon('mail')} <div><b>${BRAND.email}</b><span>We reply within one working day</span></div> ${icon('external')} </a> <div class="contact-card contact-card--static reveal"> ${icon('pin')} <div><b>${BRAND.address.line1}</b><span>${BRAND.address.city}, ${BRAND.address.county}, ${BRAND.address.postcode}</span></div> </div> <div class="contact-card contact-card--static reveal"> ${icon('clock')} <div><b>Opening hours</b><span>${BRAND.hours}</span></div> </div> </div> <div class="formcard reveal"> <h2>Send an enquiry</h2> <p>Tell us the destination, the dates and who is travelling. We will reply with the visa you need.</p> <form class="form" action="https://formsubmit.co/${BRAND.email}" method="POST"> <input type="hidden" name="_subject" value="New website enquiry - Visalade"> <input type="hidden" name="_next" value="${BRAND.domain}/thank-you.html"> <input type="hidden" name="_template" value="table"> <input type="hidden" name="_captcha" value="false"> <input type="text" name="_honey" style="display:none" tabindex="-1" autocomplete="off" aria-hidden="true"> <div class="form__row"> <div class="field"><label for="c-name">Full name</label><input id="c-name" name="name" type="text" autocomplete="name" required></div> <div class="field"><label for="c-phone">Phone or WhatsApp</label><input id="c-phone" name="phone" type="tel" autocomplete="tel" required></div> </div> <div class="field"><label for="c-email">Email</label><input id="c-email" name="email" type="email" autocomplete="email" required></div> <div class="form__row"> <div class="field"><label for="c-dest">Destination</label> <select id="c-dest" name="destination" required> <option value="">Select a country</option> ${COUNTRIES.map((c) => `<option>${c.name}</option>`).join('')} <option>Not sure yet</option> </select> </div> <div class="field"><label for="c-date">Travel date</label><input id="c-date" name="travel_date" type="date"></div> </div> <div class="field"><label for="c-message">Anything we should know?</label><textarea id="c-message" name="message" rows="4" placeholder="Purpose of travel, number of travellers, passport you hold..."></textarea></div> <label class="consent"><input type="checkbox" name="consent" required> <span>I agree to be contacted about this enquiry and have read the <a href="privacy-policy.html">privacy policy</a>.</span></label> <button class="btn btn--primary btn--block" type="submit">Send enquiry ${icon('arrow')}</button> </form> </div> </div> </section> `; return page({ title: 'Contact Visalade | WhatsApp, Phone & Email | UK Visa Support', description: 'Contact Visalade by WhatsApp, phone or email. Tell us your destination and travel dates and we will confirm the Schengen visa you need.', canonical: 'contact.html', active: 'contact', content, jsonLd: baseJsonLd() }); } /* ----------------------------------------------------------------- APPLY */ function applyPage() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Start an application' }], eyebrow: 'Start an application', title: 'Three minutes now. <em>No guesswork later.</em>', text: 'Tell us the basics and we will come back with the visa, the documents and the fee. You do not pay anything on this form.', compact: true })} <section class="section section--tight"> <div class="shell apply-grid"> <div class="formcard reveal"> <div class="form-progress" aria-hidden="true"><span id="formBar"></span></div> <p class="form-step-label" id="stepLabel">Step 1 of 3 &middot; Your trip</p> <form class="form" id="applyForm" action="https://formsubmit.co/${BRAND.email}" method="POST"> <input type="hidden" name="_subject" value="New application enquiry - Visalade"> <input type="hidden" name="_next" value="${BRAND.domain}/thank-you.html"> <input type="hidden" name="_template" value="table"> <input type="hidden" name="_captcha" value="false"> <input type="text" name="_honey" style="display:none" tabindex="-1" autocomplete="off" aria-hidden="true"> <div class="form-step is-active" data-step="1"> <h2>Where are you going?</h2> <div class="form__row"> <div class="field"><label for="a-dest">Main destination</label> <select id="a-dest" name="destination" required> <option value="">Select a country</option> ${COUNTRIES.map((c) => `<option>${c.name}</option>`).join('')} <option>Not sure yet</option> </select> </div> <div class="field"><label for="a-purpose">Purpose of travel</label> <select id="a-purpose" name="purpose" required> <option value="">Select</option> <option>Tourism / holiday</option> <option>Business</option> <option>Family or friends</option> <option>Study</option> <option>Other</option> </select> </div> </div> <div class="form__row"> <div class="field"><label for="a-arrive">Arrival date</label><input id="a-arrive" name="arrival" type="date" required></div> <div class="field"><label for="a-depart">Return date</label><input id="a-depart" name="departure" type="date" required></div> </div> <div class="form__row"> <div class="field"><label for="a-travellers">Travellers</label><input id="a-travellers" name="travellers" type="number" min="1" max="20" value="1" required></div> <div class="field"><label for="a-package">Service</label> <select id="a-package" name="package"> <option value="full">Full application support &mdash; &pound;165</option> <option value="slot">Appointment booking &mdash; &pound;99</option> <option value="premium">Premium support &mdash; &pound;250</option> <option value="advice">Not sure &mdash; advise me</option> </select> </div> </div> <div class="form__nav"><span></span><button class="btn btn--primary" type="button" data-next>Continue ${icon('arrow')}</button></div> </div> <div class="form-step" data-step="2"> <h2>Who is travelling?</h2> <div class="form__row"> <div class="field"><label for="a-first">First name</label><input id="a-first" name="first_name" type="text" autocomplete="given-name" required></div> <div class="field"><label for="a-last">Last name</label><input id="a-last" name="last_name" type="text" autocomplete="family-name" required></div> </div> <div class="form__row"> <div class="field"><label for="a-email">Email</label><input id="a-email" name="email" type="email" autocomplete="email" required></div> <div class="field"><label for="a-phone">Phone or WhatsApp</label><input id="a-phone" name="phone" type="tel" autocomplete="tel" required></div> </div> <div class="form__row"> <div class="field"><label for="a-nationality">Passport nationality</label><input id="a-nationality" name="nationality" type="text" placeholder="e.g. Indian, Nigerian, Pakistani" required></div> <div class="field"><label for="a-status">UK status</label> <select id="a-status" name="uk_status"> <option value="">Select</option> <option>British citizen</option> <option>Indefinite leave to remain</option> <option>Visa / limited leave</option> <option>Student visa</option> <option>Other</option> </select> </div> </div> <div class="form__nav"><button class="btn btn--ghost" type="button" data-prev>${icon('arrow')} Back</button><button class="btn btn--primary" type="button" data-next>Continue ${icon('arrow')}</button></div> </div> <div class="form-step" data-step="3"> <h2>Anything else?</h2> <div class="field"><label for="a-message">Tell us about the trip or any concerns</label><textarea id="a-message" name="message" rows="5" placeholder="Previous refusals, tight deadlines, complex itinerary, family applications..."></textarea></div> <label class="consent"><input type="checkbox" name="consent" required> <span>I agree to be contacted about this enquiry and have read the <a href="privacy-policy.html">privacy policy</a>.</span></label> <div class="form__nav"><button class="btn btn--ghost" type="button" data-prev>${icon('arrow')} Back</button><button class="btn btn--primary" type="submit">Send my application ${icon('arrow')}</button></div> <p class="form-note">${icon('lock')} This form does not take payment. We will confirm the fee before any work begins.</p> </div> </form> </div> <aside class="sidebar reveal"> <div class="sidecard"> <span class="sidecard__eyebrow">What happens next</span> <ol class="mini-steps"> <li><b>We read your enquiry</b><span>Usually within one working day.</span></li> <li><b>We confirm the visa</b><span>Including the right consulate.</span></li> <li><b>We quote in writing</b><span>No obligation to proceed.</span></li> <li><b>We start on your file</b><span>With a &pound;49 deposit, if you choose full support.</span></li> </ol> <div class="sidecard__divider"></div> <p class="small"><b>Prefer to talk?</b><br>WhatsApp ${BRAND.phone} and a consultant will reply during office hours.</p> <a class="btn btn--ghost btn--block" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp us</a> </div> </aside> </div> </section> `; return page({ title: 'Start a Schengen Visa Application | Visalade', description: 'Start your Schengen visa application online. Tell us your destination and dates and a UK consultant will confirm the visa, documents and fee. No payment on this form.', canonical: 'apply.html', active: 'apply', content, jsonLd: baseJsonLd() }); } /* ------------------------------------------------------------------ BLOG */ function blogIndex() { const featured = BLOG_POSTS[0]; const rest = BLOG_POSTS.slice(1); const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Blog' }], eyebrow: 'Notes from the desk', title: 'Practical visa guides, <em>no filler.</em>', text: 'Documents, consulates, refusals and the small details that decide whether a file moves smoothly. Written by the team that prepares them.', compact: true })} <section class="section section--tight"> <div class="shell"> <a class="featured reveal" href="blog/${featured.slug}.html"> <div class="featured__media"><img src="${img(featured.imgId, 1200, 78)}" alt="${featured.alt}" loading="lazy" width="1200" height="750"></div> <div class="featured__body"> <span class="post-meta">${featured.category} &middot; ${featured.date} &middot; ${featured.read}</span> <h2>${featured.title}</h2> <p>${featured.excerpt}</p> <span class="textlink">Read the guide ${icon('arrow')}</span> </div> </a> <div class="post-grid"> ${rest.map((p) => `<a class="post-card reveal" href="blog/${p.slug}.html"> <div class="post-card__media"><img src="${img(p.imgId, 700, 75)}" alt="${p.alt}" loading="lazy" width="700" height="470"></div> <div class="post-card__body"> <span class="post-meta">${p.category} &middot; ${p.read}</span> <h2>${p.title}</h2> <p>${p.excerpt}</p> <span class="textlink">Read ${icon('arrow')}</span> </div> </a>`).join('')} </div> </div> </section> ${ctaBand({ eyebrow: 'Need an answer now?', title: 'Ask us directly.', text: 'Send your destination and dates on WhatsApp. We will tell you what the visa involves, without a sales script.' })} `; return page({ title: 'Schengen Visa Blog | Documents, Consulates & Refusals | Visalade', description: 'Practical Schengen visa guides from a UK consultancy: document checklists, choosing the right consulate, refusal next steps and planning advice.', canonical: 'blog.html', active: 'blog', content, jsonLd: baseJsonLd() }); } function blogPost(p) { const others = BLOG_POSTS.filter((x) => x.slug !== p.slug); const content = ` <section class="article-hero"> <div class="shell article-hero__inner"> ${breadcrumbs([{ label: 'Home', href: 'index.html' }, { label: 'Blog', href: 'blog.html' }, { label: p.title }])} <span class="post-meta">${p.category} &middot; ${p.date} &middot; ${p.read}</span> <h1>${p.title}</h1> <p class="article-hero__lede">${p.description}</p> </div> </section> <div class="shell"> <div class="article-cover"><img src="${img(p.imgId, 1600, 80)}" alt="${p.alt}" width="1600" height="900" fetchpriority="high"></div> </div> <section class="section section--tight"> <div class="shell article-layout"> <article class="prose article-body"> ${p.body} <div class="article-foot"> <span>Written by the Visalade team</span> <a class="textlink" href="apply.html">Start an application ${icon('arrow')}</a> </div> </article> <aside class="sidebar"> <div class="sidecard"> <span class="sidecard__eyebrow">Need a hand?</span> <h3>We prepare the file for you.</h3> <p>Document checks, appointment booking and filing for all 29 Schengen countries.</p> <a class="btn btn--primary btn--block" href="apply.html">Start my application ${icon('arrow')}</a> <a class="btn btn--ghost btn--block" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} Ask a question</a> </div> </aside> </div> </section> <section class="section section--cream"> <div class="shell"> ${sectionHead({ eyebrow: 'Keep reading', title: 'More from the <em>desk.</em>' })} <div class="post-grid post-grid--2"> ${others.map((o) => `<a class="post-card reveal" href="blog/${o.slug}.html"> <div class="post-card__media"><img src="${img(o.imgId, 700, 75)}" alt="${o.alt}" loading="lazy" width="700" height="470"></div> <div class="post-card__body"><span class="post-meta">${o.category} &middot; ${o.read}</span><h2>${o.title}</h2><span class="textlink">Read ${icon('arrow')}</span></div> </a>`).join('')} </div> </div> </section> ${ctaBand({})} `; return page({ title: `${p.title} | Visalade`, description: p.description, canonical: `blog/${p.slug}.html`, active: 'blog', type: 'article', content, jsonLd: [ ...baseJsonLd(), { '@context': 'https://schema.org', '@type': 'Article', headline: p.title, description: p.description, image: img(p.imgId, 1200, 80), datePublished: p.iso, dateModified: p.iso, author: { '@type': 'Organization', name: BRAND.name }, publisher: { '@id': `${BRAND.domain}/#organization` }, mainEntityOfPage: `${BRAND.domain}/blog/${p.slug}.html` } ] }); } /* ----------------------------------------------------------- REQUIREMENTS */ function requirements() { const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Document checklist' }], eyebrow: 'Document checklist', title: 'Everything the consulate <em>expects.</em>', text: 'A practical, country-neutral checklist for a Schengen short-stay application from the UK. Your exact list depends on your destination, nationality and purpose of travel &mdash; we confirm it before you start.', actions: `<a class="btn btn--primary" href="apply.html">Get my personal checklist ${icon('arrow')}</a>`, stats: [ { value: '8', label: 'Core document groups' }, { value: '3&ndash;6', label: 'Months of bank statements' }, { value: '&euro;30k', label: 'Minimum insurance cover' }, { value: '90/180', label: 'Maximum stay' } ] })} <section class="section"> <div class="shell content-grid"> <div class="prose reveal"> <h2>1. Identity and status</h2> <ul> <li>Passport valid for at least three months beyond your planned return, issued within the last ten years</li> <li>Previous passports, if they contain Schengen visas</li> <li>UK residence permit, eVisa share code or legacy BRP, if you are not a British citizen</li> <li>Two recent colour photographs to the current Schengen specification</li> </ul> <h2>2. The application form</h2> <ul> <li>Completed, dated and signed application form</li> <li>Names, dates and passport details matching your passport exactly</li> <li>Travel dates that match your bookings</li> </ul> <h2>3. Travel evidence</h2> <ul> <li>Flight reservations showing your name and dates</li> <li>Hotel or accommodation bookings covering every night</li> <li>Invitation letter and host documents, if staying with friends or family</li> <li>A short itinerary for multi-country trips</li> </ul> <h2>4. Money</h2> <ul> <li>Bank statements for the last three to six months</li> <li>Payslips or pension statements</li> <li>Sponsorship letter and sponsor's statements, if someone else is paying</li> <li>An explanation for any large or unusual deposits</li> </ul> <h2>5. Employment, study or business</h2> <ul> <li>Employer letter confirming role, salary and approved leave</li> <li>Self-employment evidence: registration, invoices, tax returns</li> <li>School or university letter for students</li> <li>Retirement or pension evidence</li> </ul> <h2>6. Insurance</h2> <ul> <li>Travel insurance covering the full trip and all Schengen countries</li> <li>At least &euro;30,000 of medical emergency cover, including repatriation</li> <li>Policy dates that start before you leave and end after you return</li> </ul> <h2>7. Ties to the UK</h2> <ul> <li>Proof of address</li> <li>Family, property or study evidence, where relevant</li> <li>A clear reason to return to the UK</li> </ul> <h2>8. The cover letter</h2> <ul> <li>One page explaining who you are, where you are going, why and how it is funded</li> <li>Facts that match the rest of the file</li> <li>An explanation of anything unusual, such as a previous refusal or a gap in employment</li> </ul> <h2>Common reasons files are delayed</h2> <ul> <li>A booking that does not cover the last night</li> <li>A bank statement that is older than the consulate allows</li> <li>A name or date that differs between documents</li> <li>Insurance that covers the wrong dates or countries</li> <li>Applying to the wrong consulate for the itinerary</li> </ul> <p>We check all of the above before anything is submitted. If you would like us to build the checklist for your trip, <a href="apply.html">start an application</a> or send us a message.</p> </div> <aside class="sidebar reveal"> <div class="sidecard"> <span class="sidecard__eyebrow">Full support from</span> <div class="sidecard__price">&pound;165 <small>per traveller</small></div> <p>Includes your personalised checklist, a line-by-line document review and the appointment.</p> <a class="btn btn--primary btn--block" href="apply.html?package=full">Start my application ${icon('arrow')}</a> <a class="btn btn--ghost btn--block" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} Ask about my documents</a> </div> </aside> </div> </section> ${ctaBand({ title: 'Not sure if your documents are enough?', text: 'Send us a list of what you have. We will tell you what is missing before you book an appointment.' })} `; return page({ title: 'Schengen Visa Document Checklist | UK Applicants | Visalade', description: 'A practical Schengen visa document checklist for UK applicants: passport, photos, insurance, bank statements, employment proof, accommodation and cover letter.', canonical: 'requirements.html', content, jsonLd: baseJsonLd() }); } /* ------------------------------------------------------------- THANK YOU */ function thankYou() { const content = ` <section class="section thankyou"> <div class="shell thankyou__inner"> <span class="thankyou__icon">${icon('check')}</span> <span class="eyebrow">Enquiry received</span> <h1>Thank you. <em>We have it.</em></h1> <p>Your enquiry is with the team. We usually reply within one working day, Monday to Saturday. If it is urgent, message us on WhatsApp with your name and destination.</p> <div class="btn-row center"> <a class="btn btn--primary" href="${wa()}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp the team</a> <a class="btn btn--ghost" href="index.html">Back to the site</a> </div> <p class="small muted">No payment has been taken. We will confirm the visa and the fee before any work begins.</p> </div> </section> `; return page({ title: 'Thank You | Visalade', description: 'Your Schengen visa enquiry has been received. A UK consultant will reply within one working day.', canonical: 'thank-you.html', content, noindex: true }); } /* ---------------------------------------------------------------- 404 */ function notFound() { const content = ` <section class="section thankyou"> <div class="shell thankyou__inner"> <span class="eyebrow">404</span> <h1>That page has <em>flown.</em></h1> <p>The link may be old, or the page may have moved. Start with the destinations or send us a message.</p> <div class="btn-row center"> <a class="btn btn--primary" href="visas.html">All 29 countries ${icon('arrow')}</a> <a class="btn btn--ghost" href="index.html">Home</a> </div> </div> </section> `; return page({ title: 'Page Not Found | Visalade', description: 'The page you were looking for could not be found.', canonical: '404.html', content, noindex: true }); } /* -------------------------------------------------------------- COUNTRY */ function countryPage(c) { const countryFaqs = [ { q: `Do I need a visa for ${c.name}?`, a: `If you travel on a British passport, you do not need a visa for a short trip to ${c.name} or anywhere else in the Schengen area. If you hold another passport, a Schengen visa may be required. We check your nationality and UK immigration status before advising.` }, { q: `Which consulate handles ${c.name} visa applications?`, a: `${c.name} visa applications from the UK are handled by the official ${c.name} visa application centre or consulate. The exact centre depends on your route and residence. We confirm the correct one before any fee is paid.` }, { q: `How long does a ${c.name} Schengen visa take?`, a: 'Most applications are decided within 15 calendar days of the consulate receiving the file, and many are faster. Complex files can take up to 45 days. Appointment availability is separate and varies by season.' }, { q: `How much does the ${c.name} visa cost?`, a: `The government fee for a short-stay Schengen visa is normally &euro;90 for an adult, paid to the official channel. Our service fee starts at &pound;99 for appointment booking, or &pound;165 for full application support. Government and visa-centre fees are separate.` }, { q: `Can you book my ${c.name} appointment?`, a: `Yes. We monitor availability at the ${c.name} visa application centre and book a slot in your name. If you already have an appointment, we can build the document pack around it.` }, { q: `What if my ${c.name} visa is refused?`, a: 'We explain the refusal reasons and set out your options: an appeal where one is available, a fresh application, or a change of plan. Premium clients get a full post-decision review. No consultancy can guarantee approval.' } ]; const content = ` ${pageHero({ crumbs: [{ label: 'Home', href: 'index.html' }, { label: 'Visas', href: 'visas.html' }, { label: c.name }], eyebrow: `${c.name} &middot; Schengen visa`, title: `${c.name} visa, <em>handled.</em>`, text: `A ${c.name} Schengen visa lets you travel to ${c.name} and the rest of the Schengen area for up to 90 days in any 180-day period. We prepare the file, book the appointment and keep you updated until the decision.`, actions: `<a class="btn btn--primary" href="apply.html?destination=${encodeURIComponent(c.name)}">Start my application ${icon('arrow')}</a><a class="btn btn--ghost" href="${wa(`Hi Visalade, I need help with a ${c.name} Schengen visa.`)}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp us</a>`, aside: `<div class="factcard"> <div class="factcard__media"><img src="${img(c.imgId, 1000, 80)}" alt="${c.alt}" width="1000" height="640" fetchpriority="high"></div> <div class="facts"> <div class="fact"><span>Service from</span><b>&pound;99</b></div> <div class="fact"><span>Government fee</span><b>&euro;90</b></div> <div class="fact"><span>Decision time</span><b>15&ndash;45 days</b></div> <div class="fact"><span>Maximum stay</span><b>90/180</b></div> </div> <div class="factcard__foot">${icon('pin')} Main destination: ${c.city} and across ${c.name}</div> </div>` })} <section class="section"> <div class="shell content-grid"> <div class="prose reveal"> <h2>Do I need a ${c.name} visa?</h2> <p>It depends on the passport you hold, not where you live. British passport holders can visit ${c.name} for short tourism, business or family trips without a visa. If you hold a non-British passport, you may need a Schengen visa even if you have lived in the UK for years.</p> <p>${c.name} is part of the Schengen area, so the visa also lets you travel to the other Schengen countries during the same trip, up to 90 days in any 180-day period. If ${c.name} is your main destination &mdash; the country where you will spend the most nights &mdash; this is the consulate that should receive your application.</p> <p>If your itinerary takes in several countries, read our guide to <a href="blog/which-schengen-country-to-apply-to.html">choosing the right consulate</a> before booking anything.</p> <h2>Documents for a ${c.name} visa</h2> <ul> <li>Passport valid for at least three months beyond your return, issued within the last ten years</li> <li>UK residence permit, eVisa share code or legacy BRP, if you are not a British citizen</li> <li>Two recent Schengen-specification photographs</li> <li>Completed ${c.name} application form</li> <li>Travel insurance with at least &euro;30,000 medical cover, valid across the Schengen area</li> <li>Flight reservations and accommodation for every night</li> <li>Bank statements for the last three to six months</li> <li>Employer, study or business evidence</li> <li>Previous Schengen visas or refusal letters, if any</li> <li>A short cover letter explaining the trip</li> </ul> <p>This is the country-neutral list. The ${c.name} centre may ask for additional evidence depending on your purpose of travel. We confirm the exact list before you start gathering documents.</p> <h2>How we prepare a ${c.name} application</h2> <ol class="numbered"> <li><b>Check the route.</b> We confirm that ${c.name} is the correct main destination and identify the right visa application centre.</li> <li><b>Build the checklist.</b> You get a list tailored to your nationality, status and trip, not a generic PDF.</li> <li><b>Review the file.</b> Names, dates, balances and bookings are compared line by line. We tell you what to fix before submission.</li> <li><b>Book the appointment.</b> We find a slot at the ${c.name} centre and tell you exactly what to bring.</li> <li><b>File and track.</b> We explain how to submit and how to follow the decision until your passport is returned.</li> </ol> <h2>Where to apply in the UK</h2> <p>Applications for ${c.name} are handled by the official ${c.name} visa application centre in the UK. The centre may be operated by VFS Global, TLScontact, BLS International or the consulate itself, depending on the country. We confirm the current provider, address and appointment rules before you pay a government fee.</p> <h2>How long will it take?</h2> <p>Most ${c.name} visa applications are decided within 15 calendar days of the file reaching the consulate, and many are faster. Complex cases can take up to 45 days. Appointment availability is the variable we cannot control, so we recommend starting four to six weeks before travel where possible.</p> <h2>FAQs</h2> </div> <aside class="sidebar reveal"> <div class="sidecard"> <span class="sidecard__eyebrow">${c.name} support from</span> <div class="sidecard__price">&pound;165 <small>per traveller</small></div> <p>Or start with a &pound;49 deposit and pay the balance when your appointment is booked.</p> <a class="btn btn--primary btn--block" href="apply.html?destination=${encodeURIComponent(c.name)}">Start my application ${icon('arrow')}</a> <a class="btn btn--ghost btn--block" href="${wa(`Hi Visalade, I need help with a ${c.name} Schengen visa.`)}" target="_blank" rel="noopener">${icon('whatsapp')} WhatsApp us</a> <ul class="ticks ticks--sm"> <li>${icon('check')} ${c.name} appointment booking</li> <li>${icon('check')} Document review</li> <li>${icon('check')} Application filing</li> <li>${icon('check')} One named consultant</li> </ul> </div> </aside> </div> </section> <section class="section section--tint"> <div class="shell"> ${sectionHead({ eyebrow: 'FAQs', title: `${c.name} visa <em>questions.</em>` })} ${faqBlock(countryFaqs, `faq-${c.slug}`)} </div> </section> <section class="section"> <div class="shell"> ${sectionHead({ eyebrow: 'Packages', title: 'Choose how much help <em>you want.</em>', text: 'The same fixed pricing for every Schengen country.' })} <div class="price-grid">${PACKAGES.map((p) => packageCard(p)).join('')}</div> </div> </section> <section class="section section--cream"> <div class="shell"> ${sectionHead({ eyebrow: 'Also travelling', title: 'Other Schengen <em>destinations.</em>' })} ${countryPills()} </div> </section> ${ctaBand({ title: `Ready to start your ${c.name} application?`, text: 'Send your travel dates and we will confirm the visa, the centre and the next step. The first conversation is free.', waText: `Hi Visalade, I'd like to start a ${c.name} Schengen visa application.` })} `; return page({ title: `${c.name} Schengen Visa from the UK | Requirements & Support | Visalade`, description: `${c.name} Schengen visa support for UK residents. Requirements, documents, fees and appointment booking, with a dedicated UK consultant. Service from £99.`, canonical: `${c.slug}.html`, content, jsonLd: [ ...baseJsonLd(), { '@context': 'https://schema.org', '@type': 'BreadcrumbList', itemListElement: [ { '@type': 'ListItem', position: 1, name: 'Home', item: `${BRAND.domain}/` }, { '@type': 'ListItem', position: 2, name: 'Visas', item: `${BRAND.domain}/visas.html` }, { '@type': 'ListItem', position: 3, name: c.name, item: `${BRAND.domain}/${c.slug}.html` } ] }, faqJsonLd(countryFaqs) ] }); } module.exports = { home, visas, schengen, howItWorks, pricing, about, reviewsPage, faqPage, contact, applyPage, blogIndex, blogPost, requirements, thankYou, notFound, countryPage }; 